argv:
$ErrorActionPreference='SilentlyContinue'
$roots=@()
Get-ChildItem 'E:\' -Directory -Force | Where-Object {$_.Name -ne 'manhwa'} | ForEach-Object {
  $p=$_.FullName
  if(Test-Path (Join-Path $p '.git')){
    $roots += [pscustomobject]@{path=$p;git=$true;remote=((git -C $p remote get-url origin 2>$null) -join '')}
  }
}
$runnerServices=Get-CimInstance Win32_Service | Where-Object {
  $_.Name -match 'actions.runner|github.*runner|runner' -or $_.DisplayName -match 'GitHub Actions|runner'
} | Select-Object Name,DisplayName,StartMode,State,PathName
$runnerProcs=Get-CimInstance Win32_Process | Where-Object {
  $_.CommandLine -match 'Runner.Listener|run.cmd|actions-runner'
} | Select-Object ProcessId,Name,CommandLine
$ffmpeg=(Get-Command ffmpeg -ErrorAction SilentlyContinue)
$ffprobe=(Get-Command ffprobe -ErrorAction SilentlyContinue)
$cpu=Get-CimInstance Win32_Processor | Select-Object -First 1 Name,NumberOfCores,NumberOfLogicalProcessors
$gpu=Get-CimInstance Win32_VideoController | Select-Object Name,AdapterRAM,DriverVersion
[pscustomobject]@{
  repos=$roots
  runnerServices=@($runnerServices)
  runnerProcesses=@($runnerProcs)
  ffmpeg=if($ffmpeg){$ffmpeg.Source}else{$null}
  ffprobe=if($ffprobe){$ffprobe.Source}else{$null}
  cpu=$cpu
  gpu=@($gpu)
} | ConvertTo-Json -Depth 6 -Compress
